"use client";

import * as React from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import { PauseIcon, PlayIcon } from "@hugeicons/core-free-icons";
import { IsoFigure, Line, Solid } from "@/components/anatomy/react/draw";
import { asksForStillness, follow, useInView, useStillness } from "@/components/anatomy/react/live";
import { LiveSolid, type SolidHandle } from "@/components/anatomy/live-solid";
import {
  BASE_LINES,
  BASE_PARTS,
  CAVITY_CLIP,
  CAVITY_LINES,
  CAVITY_PARTS,
  DOOR_EDGE_ON,
  DOOR_LAYERS,
  DOOR_STYLE,
  HALO,
  HEIGHT,
  SHELL_LINES,
  SHELL_PARTS,
  WIDTH,
  clockFor,
  doorLines,
  doorParts,
  poseAt,
  progressFor,
  stateText,
  tourAt,
  type DoorLayer,
  type Pose,
} from "./safe";
import "./the-safe.css";

const MOST_DT = 1 / 30;
const SEEK = 0.13; // seconds for the door to answer a reader's hand
const CAVITY = "the-safe-cavity";

/* the safe stands open: it is the frame the drawing is about, and the reader
   takes it from there */
const OPENING: Pose = poseAt(1);
const DOOR_OPENING = doorParts(OPENING.swing, OPENING.spin, OPENING.turn);
const LINE_OPENING = doorLines(OPENING.swing, OPENING.spin);

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);

/**
 * A still frame to check the drawing by: `?pose=0` holds it locked, `?pose=1`
 * holds it open, anything between scrubs to there. Development only.
 */
function posedFromQuery(): number | null {
  if (!import.meta.env.DEV || typeof window === "undefined") return null;
  const raw = new URLSearchParams(window.location.search).get("pose");
  if (raw === null) return null;
  const value = Number(raw);
  return Number.isFinite(value) ? clamp01(value) : null;
}

interface Live {
  clock: number;
  /** where the safe stands */
  pose: Pose;
  /** where a reader who has taken hold of it wants it */
  want: number;
  /** and how far it has got there */
  progress: number;
}

export interface TheSafeProps {
  theme?: "dark" | "light";
  className?: string;
  /** hold the tour if you want to drive it yourself */
  playing?: boolean;
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
}

export function TheSafe({ theme = "dark", className, playing: controlled, defaultPlaying = true, onPlayingChange }: TheSafeProps) {
  const posed = React.useMemo(posedFromQuery, []);
  const posedRef = React.useRef(posed);
  posedRef.current = posed;

  const [own, setOwn] = React.useState(defaultPlaying);
  const playing = posed === null ? (controlled ?? own) : false;
  const setPlaying = React.useCallback(
    (next: boolean) => {
      if (controlled === undefined) setOwn(next);
      onPlayingChange?.(next);
    },
    [controlled, onPlayingChange],
  );

  const root = React.useRef<HTMLDivElement | null>(null);
  const inView = useInView(root);
  const readout = React.useRef<HTMLSpanElement | null>(null);
  const doorHandles = React.useMemo(() => DOOR_STYLE.map(() => React.createRef<SolidHandle>()), []);
  const lineRefs = React.useMemo(() => LINE_OPENING.map(() => React.createRef<SVGPathElement>()), []);
  /** which face of the door the reader has: false while the outer face is to them */
  const [inward, setInward] = React.useState(OPENING.swing > DOOR_EDGE_ON);
  const facingIn = React.useRef(inward);
  const frame = React.useRef(0);
  const last = React.useRef(0);
  const grab = React.useRef(0);
  const playRef = React.useRef(playing);
  const [pressing, setPressing] = React.useState(false);

  const state = React.useRef<Live>({
    clock: posed === null ? clockFor(OPENING) : 0,
    pose: posed === null ? OPENING : poseAt(posed),
    want: posed ?? 1,
    progress: posed ?? 1,
  });

  const paint = React.useCallback(() => {
    const s = state.current;
    const door = doorParts(s.pose.swing, s.pose.spin, s.pose.turn);
    for (let index = 0; index < door.length; index++) doorHandles[index]?.current?.apply(door[index]!);
    const lines = doorLines(s.pose.swing, s.pose.spin);
    for (let index = 0; index < lines.length; index++) {
      const node = lineRefs[index]?.current;
      if (node && node.getAttribute("d") !== lines[index]!.d) node.setAttribute("d", lines[index]!.d);
    }

    /* The door's two skins take turns. While its outer face stands to the reader
       the dial and the handle are what is seen; once the swing has carried that
       face past the panel's edge the reader is looking at the door's inner
       face, and then it is the boltwork that is seen. The panel turns edge-on at
       a quarter of the swing, so that is where the skins swap places in the
       paint order — the swap is the occlusion itself, and it happens twice in a
       turn of the tour, not once a frame. */
    const inFacing = s.pose.swing > DOOR_EDGE_ON;
    if (facingIn.current !== inFacing) {
      facingIn.current = inFacing;
      setInward(inFacing);
    }

    const text = stateText(s.pose);
    if (readout.current && readout.current.textContent !== text) readout.current.textContent = text;
    const host = root.current;
    if (host) {
      const now = String(Math.round(clamp01(progressFor(s.pose)) * 100));
      if (host.getAttribute("aria-valuenow") !== now) {
        host.setAttribute("aria-valuenow", now);
        host.setAttribute("aria-valuetext", text);
      }
    }
  }, [doorHandles, lineRefs]);

  const stop = React.useCallback(() => {
    cancelAnimationFrame(frame.current);
    frame.current = 0;
  }, []);

  const run = React.useCallback(() => {
    if (frame.current) return;
    last.current = 0;
    const step = (now: number) => {
      const dt = last.current ? Math.min((now - last.current) / 1000, MOST_DT) : 1 / 60;
      last.current = now;
      const calm = asksForStillness();
      const s = state.current;
      const still = posedRef.current;
      if (still !== null) {
        s.progress = still;
        s.want = still;
        s.pose = poseAt(still);
      } else if (playRef.current && !calm) {
        s.clock += dt;
        s.pose = tourAt(s.clock);
        s.want = progressFor(s.pose);
        s.progress = s.want;
      } else {
        s.progress = calm ? s.want : follow(s.progress, s.want, dt, SEEK);
        s.pose = poseAt(s.progress);
      }
      paint();
      const settled = Math.abs(s.progress - s.want) < 1e-3;
      frame.current = still !== null || (playRef.current && !calm) || (!calm && !settled) ? requestAnimationFrame(step) : 0;
    };
    frame.current = requestAnimationFrame(step);
  }, [paint]);

  React.useEffect(() => {
    if (inView) run();
    else stop();
  }, [inView, run, stop]);

  React.useEffect(() => {
    playRef.current = playing;
    if (posedRef.current !== null) return;
    const s = state.current;
    if (playing) {
      // pick the tour up where the safe was left standing
      s.clock = clockFor(s.pose);
    } else {
      // put it down where it stands, and let the reader take it from there
      s.want = progressFor(s.pose);
      s.progress = s.want;
    }
    if (playing || inView) run();
  }, [playing, inView, run]);

  React.useEffect(() => () => stop(), [stop]);
  React.useEffect(() => paint(), [paint]);

  /* reduced motion: hold the frame the drawing is about — the safe open, its
     chamber on show — and let the reader take it from there */
  const stillness = useStillness();
  React.useEffect(() => {
    if (!stillness || posedRef.current !== null) return;
    const s = state.current;
    s.progress = 1;
    s.want = 1;
    s.pose = poseAt(1);
    paint();
  }, [stillness, paint]);

  /* The door is laid out in one of two orders, so the only thing a change of
     face costs is the swap itself: the parts, and the paths the frame writes
     into, are the same either way. */
  const layers = React.useMemo(() => {
    const build = (list: DoorLayer[]) =>
      list.flatMap((layer) => [
        ...layer.slots.map((slot) => (
          <LiveSolid
            key={`door${slot}`}
            paths={DOOR_OPENING[slot]!}
            handle={doorHandles[slot]}
            tone={DOOR_STYLE[slot]!.tone}
            crease={DOOR_STYLE[slot]!.crease}
            lit={DOOR_STYLE[slot]!.lit}
          />
        )),
        ...LINE_OPENING.flatMap((item, at) =>
          (item.face ?? "outer") === layer.ink ? [<path key={`doorink${at}`} ref={lineRefs[at]} className="iso-line" data-tone={item.tone} d={item.d} />] : [],
        ),
      ]);
    return { outward: build(DOOR_LAYERS.outward), inward: build(DOOR_LAYERS.inward) };
  }, [doorHandles, lineRefs]);

  /** the pointer reads across the frame: nought at the left, one at the right */
  const valueAt = (clientX: number) => {
    const box = root.current?.getBoundingClientRect();
    if (!box || !box.width) return null;
    return clamp01((clientX - (box.left + box.width * 0.14)) / (box.width * 0.72));
  };

  const seekTo = React.useCallback(
    (progress: number) => {
      state.current.want = clamp01(progress);
      run();
    },
    [run],
  );

  return (
    <div className={className ? `iso the-safe ${className}` : "iso the-safe"} data-theme={theme}>
      <div className="the-safe-plate">
        <div
          ref={root}
          className="the-safe-stage"
          role="slider"
          tabIndex={playing ? -1 : 0}
          data-interactive={playing ? undefined : ""}
          aria-label="A solid combination safe in isometric view, standing on a plinth: the dial spins its graduations onto a fixed index, the spoked handle comes a quarter turn out and throws the bolts, and the door swings open clear of the chamber."
          aria-readonly={playing}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={100}
          aria-valuetext="open — the chamber on show"
          style={{ touchAction: "pan-y" }}
          onPointerDown={(event) => {
            if (playing) return;
            const at = valueAt(event.clientX);
            if (at === null) return;
            event.currentTarget.setPointerCapture(event.pointerId);
            // hold the safe where it stands rather than throwing it at the pointer
            grab.current = state.current.progress - at;
            setPressing(true);
            seekTo(at + grab.current);
          }}
          onPointerMove={(event) => {
            if (playing || !pressing) return;
            const at = valueAt(event.clientX);
            if (at === null) return;
            seekTo(at + grab.current);
          }}
          onPointerUp={(event) => {
            if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
            setPressing(false);
          }}
          onPointerCancel={() => setPressing(false)}
          onKeyDown={(event) => {
            if (playing) return;
            const step = event.shiftKey ? 0.16 : 0.05;
            let next: number | null = null;
            if (event.key === "ArrowLeft" || event.key === "ArrowDown") next = state.current.want - step;
            else if (event.key === "ArrowRight" || event.key === "ArrowUp") next = state.current.want + step;
            else if (event.key === "Home") next = 0;
            else if (event.key === "End") next = 1;
            if (next === null) return;
            event.preventDefault();
            seekTo(next);
          }}
        >
          <IsoFigure
            width={WIDTH}
            height={HEIGHT}
            className="the-safe-figure"
            label="A solid combination safe in isometric view, standing on a plinth: the dial spins its graduations onto a fixed index, the spoked handle comes a quarter turn out and throws the bolts, and the door swings open clear of the chamber"
          >
            <defs>
              <clipPath id={CAVITY}>
                <path d={CAVITY_CLIP} />
              </clipPath>
            </defs>

            <path className="iso-halo" d={HALO} />

            {BASE_PARTS.map((item, index) => (
              <Solid key={`base${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
            ))}
            {BASE_LINES.map((item, index) => (
              <Line key={`baseink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}
            {SHELL_PARTS.map((item, index) => (
              <Solid key={`shell${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
            ))}
            {SHELL_LINES.map((item, index) => (
              <Line key={`shellink${index}`} d={item.d} tone={item.tone} className={item.className} free={item.free} />
            ))}

            {/* the chamber: only the three surfaces the camera can see, clipped
                to the opening so nothing leaks over the face around it */}
            <g clipPath={`url(#${CAVITY})`}>
              {CAVITY_PARTS.map((item, index) => (
                <Solid key={`cavity${index}`} paths={item.paths} tone={item.tone} crease={item.crease} lit={item.lit} className={item.mark} />
              ))}
              {CAVITY_LINES.map((item, index) => (
                <Line key={`cavityink${index}`} d={item.d} tone={item.tone} className={item.className} />
              ))}
            </g>

            {/* the door, rebuilt whole every frame: its solids first, so the
                retracted bolts hide behind the panel, then its ink */}
            {/* the door, one skin to the reader at a time: its solids, with the
                ink riding on the run of parts it was drawn for */}
            <g className="the-safe-door">{inward ? layers.inward : layers.outward}</g>
          </IsoFigure>
        </div>

        <span ref={readout} className="the-safe-readout" data-readout="">
          {stateText(OPENING)}
        </span>

        <button
          type="button"
          className="the-safe-control"
          aria-label={playing ? "Pause the animation and take the handle" : "Play the animation"}
          title={playing ? "Pause" : "Play"}
          onClick={() => setPlaying(!playing)}
        >
          <span className="the-safe-swap" aria-hidden="true">
            <HugeiconsIcon className="the-safe-glyph" data-on={playing ? "" : undefined} icon={PauseIcon} size={16} strokeWidth={1.6} />
            <HugeiconsIcon className="the-safe-glyph" data-on={playing ? undefined : ""} icon={PlayIcon} size={16} strokeWidth={1.6} />
          </span>
        </button>
      </div>
    </div>
  );
}

/* The Safe — a heavy combination safe on levelling feet. One number drives the
   whole figure: how far the reader has turned it. Three movements follow in
   order, and they are the three a hand makes on a real safe: the dial spins and
   brings its graduations onto the fixed index; the handle comes a quarter turn
   out and the bolts ride out of the door's edges; then the door swings clear of
   the opening on its hinge, and the chamber it was covering is on show.

   Nothing here is cut away and nothing is transparent. The shell is a stack of
   solid slabs, the chamber is a real recess with its own walls, and the door is
   one rigid panel rebuilt whole every frame: it spans z, and a turn about a
   vertical line is only a screen matrix for geometry lying at one height. The
   door is also a real door in that it has two faces, and it shows the right one:
   the dial, the plate and the handle outside, the boltwork inside.

   The one lit part is the index on the dial's plate. It never moves; the
   graduations turn past it. */
import {
  boxCorners,
  corners,
  cylinder,
  depthOf,
  fitProjection,
  haloOf,
  insetPlan,
  lineOnTop,
  pathOf,
  planOutline,
  pointsAt,
  slabOf,
  sideSeam,
  type LineTone,
  type Plan,
  type Plane,
  type Point3,
  type Projection,
  type SolidPaths,
  type Tone,
} from "@/components/anatomy/iso-kit";
import { circleSection, frameAlong, prismOf, rectSection, type Frame } from "@/components/anatomy/axis-parts";

export const WIDTH = 660;
export const HEIGHT = 470;
const PAD = 22;
const RAD = Math.PI / 180;
const TAU = Math.PI * 2;

const clamp01 = (x: number) => (x < 0 ? 0 : x > 1 ? 1 : x);
const smooth01 = (x: number) => {
  const t = clamp01(x);
  return t * t * (3 - 2 * t);
};
/** an ease that runs past its mark and settles onto it, for the dial landing on
    its graduation */
const easeBack = (x: number) => {
  const t = clamp01(x);
  const c1 = 1.70158;
  return 1 + (c1 + 1) * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};
const easeInOut = (x: number) => {
  const t = clamp01(x);
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};
/** bisect a monotone ease, so a reader who takes over picks the number up where
    it was standing */
function solve(f: (t: number) => number, want: number) {
  let low = 0;
  let high = 1;
  for (let step = 0; step < 24; step++) {
    const mid = (low + high) / 2;
    if (f(mid) < want) low = mid;
    else high = mid;
  }
  return (low + high) / 2;
}

/* ——— the plinth, on four levelling feet ——— */
export const PLINTH: Plan = { x: -118, y: -104, w: 236, d: 208, r: 16 };
const PLINTH_H = 22;
export const DECK_Z = 26;
const FOOT_Z = -16;

/* ——— the cabinet: a stack of solid slabs ——— */
export const BODY: Plan = { x: -96, y: -78, w: 192, d: 156, r: 12 };
export const BODY_Z0 = DECK_Z;
export const BODY_Z1 = 186;
const CROWN: Plan = insetPlan(BODY, 6);
const CROWN_Z1 = 196;
/** the cabinet's front face, and the aperture cut into it */
export const FACE_Y = BODY.y + BODY.d;
const APERTURE = { x0: -72, x1: 72, z0: 46, z1: 166 };
/** how deep the chamber runs behind the face */
const BACK_Y = 36;
/** the raised frame the shut door seals onto */
const FRAME = { x0: -84, x1: 84, z0: 34, z1: 178, out: 4 };

/* ——— the door: one rigid panel across the front, hinged at the left ——— */
export const DOOR = (() => {
  const y0 = FACE_Y + FRAME.out;
  const t = 14;
  return { x0: -82, x1: 82, y0, y1: y0 + t, z0: 38, z1: 174, t };
})();
/*
  The vertical line the door turns on: a barrel on the door's own left-hand
  edge, at the door's mid-thickness, the way a real door hangs off its knuckles.
  The edge sits on the axis, so nothing bridges a gap and there is nothing to
  read as a floating panel; the four units are the knuckle's own depth, out to
  the pin.

  Hung on the left, the door swings out and away to the reader's left, clear of
  the opening: the chamber is never behind it. The price is that the door's
  outer face crosses the camera's quarter partway open, and from there the
  reader is looking at the door's inner face — see doorParts, which stocks it.
*/
export const HINGE: Plane = [DOOR.x0 - 4, (DOOR.y0 + DOOR.y1) / 2];
const DOOR_W = DOOR.x1 - DOOR.x0;
const DOOR_T = DOOR.t;
const DOOR_H = DOOR.z1 - DOOR.z0;
const DOOR_MY = (DOOR.y0 + DOOR.y1) / 2;
const DOOR_MZ = (DOOR.z0 + DOOR.z1) / 2;

/* what sits on the door: a dial over the handle */
export const DIAL: Plane = [0, 126];
const DIAL_R = 30;
const PLATE_R = 36;
const DIAL_OUT = 6; // the graduation plate's thickness on the door
const CAP_OUT = 15; // the dial's own face, off the door
export const HANDLE: Plane = [0, 64];
const HANDLE_R = 20;

export const SPIN_TURNS = 3;
const DIAL_SPIN = SPIN_TURNS * TAU;
/** How far the door swings. It hangs on the left, so this carries the free edge
    out and away to the reader's left, clear of the opening: the chamber ends up
    beside the door rather than behind it. A door swings out of its frame, not
    through it, so the free edge travels away from the shell. */
export const OPEN = 75 * RAD;
/** how far the bolts ride out of the door's edges */
const BOLT_STROKE = 10;
const BOLT_X = 46;
const BOLT_R = 5;

/* ——— the swing: one rigid body, placed whole ——— */
function swung([x, y, z]: Point3, phi: number): Point3 {
  const c = Math.cos(phi);
  const s = Math.sin(phi);
  const dx = x - HINGE[0];
  const dy = y - HINGE[1];
  return [HINGE[0] + dx * c - dy * s, HINGE[1] + dx * s + dy * c, z];
}
const swungDir = ([x, y, z]: Point3, phi: number): Point3 => [x * Math.cos(phi) - y * Math.sin(phi), x * Math.sin(phi) + y * Math.cos(phi), z];
const swungFrame = (frame: Frame, phi: number): Frame => ({ o: swung(frame.o, phi), a: swungDir(frame.a, phi), u: swungDir(frame.u, phi), v: swungDir(frame.v, phi) });

/** A frame standing on a face whose outward normal is +y. In the section, the
    first coordinate runs up the world's z and the second across the world's x,
    so a section angle of nought points straight up the face. */
const faceFrame = (across: number, up: number, out: number, at: number): Frame => ({ o: [across, at + out, up], a: [0, 1, 0], u: [0, 0, 1], v: [1, 0, 0] });
/** the same on a face whose outward normal is +x */
const sideFrame = (y: number, z: number, out: number, at: number): Frame => ({ o: [at + out, y, z], a: [1, 0, 0], u: [0, 0, 1], v: [0, 1, 0] });
const faceDisc = (radius: number, steps: number, angle = 0, at: Plane = [0, 0]): Plane[] =>
  Array.from({ length: steps }, (_, index) => {
    const t = (index / steps) * TAU + angle;
    return [at[1] + radius * Math.cos(t), at[0] + radius * Math.sin(t)] as Plane;
  });
const faceRect = (halfAcross: number, halfUp: number, at: Plane = [0, 0]): Plane[] => [
  [at[1] - halfUp, at[0] - halfAcross],
  [at[1] + halfUp, at[0] - halfAcross],
  [at[1] + halfUp, at[0] + halfAcross],
  [at[1] - halfUp, at[0] + halfAcross],
];
/** a world box, swept from y0 to y1 */
const block = (x0: number, x1: number, y0: number, y1: number, z0: number, z1: number, creases = true): SolidPaths =>
  prismOf(frameAlong([(x0 + x1) / 2, y0, (z0 + z1) / 2], [(x0 + x1) / 2, y1, (z0 + z1) / 2]), rectSection(x1 - x0, z1 - z0), 0, y1 - y0, P, { creases });

/* ——— the projection: the cabinet at rest, and the door at both ends ——— */
function extremes(): Point3[] {
  const points: Point3[] = [];
  const plan = (at: Plan, z0: number, z1: number) => points.push(...boxCorners(at, z0, z1));
  plan(PLINTH, FOOT_Z, DECK_Z);
  plan(BODY, BODY_Z0, BODY_Z1);
  plan(CROWN, BODY_Z1, CROWN_Z1);
  const door: Point3[] = [];
  for (const x of [DOOR.x0, DOOR.x1]) for (const y of [DOOR.y0, DOOR.y1]) for (const z of [DOOR.z0, DOOR.z1]) door.push([x, y, z]);
  door.push([DIAL[0], DOOR.y1 + 22, DIAL[1]], [HANDLE[0], DOOR.y1 + 19, HANDLE[1]]);
  for (const x of [-BOLT_X, BOLT_X]) {
    door.push([x, DOOR_MY, DOOR.z1 + BOLT_STROKE], [x, DOOR_MY, DOOR.z0 - BOLT_STROKE], [x, DOOR_MY, DOOR.z1], [x, DOOR_MY, DOOR.z0]);
  }
  /* the hinge barrel, which stands off the door's own edge, and the boss of the
     boltwork, which stands off its inner face */
  for (const x of [HINGE[0] - 6, HINGE[0] + 6]) for (const y of [HINGE[1] - 6, HINGE[1] + 6]) door.push([x, y, DOOR.z0 + 12], [x, y, DOOR.z1 - 12]);
  for (const z of [DOOR_MZ - 11, DOOR_MZ + 11]) door.push([0, DOOR.y0 - 14, z]);
  for (const phi of [0, OPEN]) for (const point of door) points.push(swung(point, phi));
  return points;
}

export const P: Projection = fitProjection(extremes(), WIDTH, HEIGHT, { pad: PAD });

/* ——— what a drawing is made of: a solid, or a line across the faces ——— */
export interface Part {
  paths: SolidPaths;
  tone: Tone;
  crease: Tone | "none";
  lit: boolean;
  mark?: string;
}
export interface Ink {
  d: string;
  tone: LineTone;
  className?: string;
  /** an end that is meant to stop in the open: only the maker's printed rules */
